package com.chubb.apac.claims.modulith.assessment.repository;import com.chubb.apac.claims.modulith.assessment.model.*;import java.util.List;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;import static org.assertj.core.api.Assertions.assertThat;
@DataJpaTest class AssessmentRepositoryTest{@Autowired AssessmentRepository repository;@Test void uniqueClaimAssessment(){Assessment a=new Assessment();a.setAssessmentId("ASM-1");a.setClaimId("CLM-1");a.setAssessorId("S1");a.setMarket(com.chubb.apac.claims.modulith.common.enums.Market.SG);a.setProductType(com.chubb.apac.claims.modulith.common.enums.ProductType.MOTOR);a.setFindings("F");a.setRecommendedDecision(RecommendedDecision.APPROVE);a.setRecommendationReason("R");a.setRiskFactors(List.of());a.setStatus(AssessmentStatus.IN_PROGRESS);a.setCreatedBy("S1");a.setUpdatedBy("S1");repository.saveAndFlush(a);assertThat(repository.findByClaimId("CLM-1")).isPresent();}}
